#!/usr/bin/env bash
# Stamps sdk/ios/VERSION into Sources/ZeotapSDK/Generated/Version.swift (the
# value behind context.library.version). Package.swift cannot read files, so
# the generated file is committed; VersionTests fails when it is stale and
# check-version.sh asserts the release tag matches. Run after bumping VERSION.
set -euo pipefail
cd "$(dirname "$0")/.."
version="$(tr -d '[:space:]' < VERSION)"
[[ "$version" =~ ^[0-9]+\.[0-9]+\.[0-9]+(-[0-9A-Za-z.-]+)?$ ]] || { echo "VERSION '$version' is not semver" >&2; exit 1; }
out="Sources/ZeotapSDK/Generated/Version.swift"
mkdir -p "$(dirname "$out")"
cat > "$out" <<EOF
// GENERATED by scripts/stamp-version.sh from sdk/ios/VERSION — do not edit.
// Stamped into context.library.version on every event.
enum SDKVersion {
    static let current = "$version"
}
EOF
echo "[stamp-version] Version.swift = $version"
